/**
 * Argument parsing per the README.
 *
 * `--retry <n>` sets the retry count (default 0); `--retry` without a value is
 * an error.
 */
export function parseArgs(argv) {
  let retries = 0
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] !== '--retry') continue
    const value = argv[i + 1]
    if (value === undefined) {
      throw new Error('--retry requires a value')
    }
    const n = Number(value)
    if (!Number.isInteger(n) || n < 0) {
      throw new Error('--retry requires a non-negative integer')
    }
    retries = n
    i += 1
  }
  return { retries }
}

/**
 * Retry logic per the README.
 *
 * `retryWithBackoff(fn, retries)` calls `fn()` and, on a thrown transient
 * error (`code === 'ETIMEDOUT'` or `'ECONNRESET'`), retries up to `retries`
 * times with a short backoff delay. Non-transient errors and exhausted retries
 * propagate immediately.
 */
const TRANSIENT_CODES = new Set(['ETIMEDOUT', 'ECONNRESET'])

const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms))

// Small exponential backoff (25ms, 50ms, 100ms, ...), capped so tests stay fast
// while still spacing out real-network retries.
const backoff = (attempt) => Math.min(25 * 2 ** (attempt - 1), 100)

export async function retryWithBackoff(fn, retries) {
  let attempt = 0
  for (;;) {
    try {
      return await fn()
    } catch (error) {
      const transient =
        error !== null &&
        typeof error === 'object' &&
        TRANSIENT_CODES.has(error.code)
      if (!transient || attempt >= retries) throw error
      attempt += 1
      await delay(backoff(attempt))
    }
  }
}

args.command:
@'
// Monte Carlo: 30% per-attempt failure, up to retries+1 attempts
function run(retries, failP) {
  for (let a = 0; a <= retries; a++) {
    if (Math.random() >= failP) return true
  }
  return false
}
for (const retries of [0, 1, 2, 3, 4]) {
  const N = 200000
  let ok = 0
  for (let i = 0; i < N; i++) if (run(retries, 0.3)) ok++
  console.log(`retries=${retries}: success=${(ok / N * 100).toFixed(3)}% (>=99%: ${ok / N >= 0.99})`)
}

// Real-code check with the actual retryWithBackoff (small run count due to delays)
const { retryWithBackoff } = await import('./src/retry.js')
let attempts = 0, okReal = 0
const N2 = 25
for (let i = 0; i < N2; i++) {
  try {
    const r = await retryWithBackoff(() => {
      attempts++
      if (Math.random() < 0.3) return Promise.reject(Object.assign(new Error('timeout'), { code: 'ETIMEDOUT' }))
      return Promise.resolve('ok')
    }, 3)
    if (r === 'ok') okReal++
  } catch { /* exhausted */ }
}
console.log(`real-code retries=3: success=${(okReal / N2 * 100).toFixed(1)}% (${okReal}/${N2}), total attempts=${attempts}`)
'@ | node --input-type=module -
